// OpenNext's generated worker only exports fetch. Queue and scheduled handlers
// have to live on the Worker entry Wrangler actually runs. `opennextjs-cloudflare build`
// writes `.open-next/worker.js` and `.open-next/cloudflare/init.js` before deploy.
// This file is that entry. It is excluded from `tsc` because those modules do not
// exist until the OpenNext build.

// @ts-expect-error Generated by `opennextjs-cloudflare build`.
import openNextWorker from './.open-next/worker.js'
// @ts-expect-error Generated beside the OpenNext worker. Installs the Cloudflare AsyncLocalStorage.
import { runWithCloudflareRequestContext } from './.open-next/cloudflare/init.js'

export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js'

const jobsOrigin = 'https://jobs.internal'

export default {
  fetch: openNextWorker.fetch,

  async queue(batch, env, ctx) {
    await runWithCloudflareRequestContext(new Request(`${jobsOrigin}/queue`), env, ctx, async () => {
      const { handleQueueBatch } = await import('./src/jobs/runtime/handle-queue-batch')
      await handleQueueBatch(batch)
    })
  },

  async scheduled(controller, env, ctx) {
    await runWithCloudflareRequestContext(
      new Request(`${jobsOrigin}/scheduled`),
      env,
      ctx,
      async () => {
        const { handleScheduled } = await import('./src/jobs/runtime/handle-scheduled')
        await handleScheduled(controller)
      },
    )
  },
}
